import{z as B,x as s,o as e,c as m,q as r,j as o,D as E,d as l,s as i,S as A,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"推理长度控制","description":"","frontmatter":{"title":"推理长度控制","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/reasoning-length-control.md","filePath":"llm/reasoning-length-control.md","lastUpdated":1791413859000}'),p={name:"llm/reasoning-length-control.md"};function d(h,a,c,C,_,D){const n=s("Mermaid");return e(),m("div",null,[a[2]||(a[2]=r('<h1 id="推理长度控制" tabindex="-1">推理长度控制 <a class="header-anchor" href="#推理长度控制" aria-label="Permalink to &quot;推理长度控制&quot;">​</a></h1><div class="epigraph"><p>把长度写成目标的一部分：同样答对，短的赢；或在预算内强迫收束，而不是事后截断。</p><footer>—— DAPO 软超长塑形；s1 预算强迫；产品侧按档位训练多条长度策略</footer></div><p><a href="/llm/overthinking">上一课</a>诊断了无价格的长度。本课写控制手段：奖励塑形、多档预算训练、解码强迫。缺口是工程：<strong>控制必须进入训练目标，解码截断只是最后闸。</strong> 接到自我验证：压长度时不要把「再验一次」全部删掉。对照 <a href="/llm/length-normalization-bias">长度归一化偏差</a>——这里不靠除 \\(|y|\\) 偷长度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>除以长度会伤害长证明。要的是条件偏序：正确集合里偏好短。实现：\\(\\tilde R = R_{\\mathrm{acc}} + p(|y|)\\)，\\(p\\) 在阈值后为负；或分层：\\(R_{\\mathrm{acc}}=0\\) 则不管长度，\\(R_{\\mathrm{acc}}=1\\) 再比长度。后者更接近「同样对则短」。DAPO 的线性尾部惩罚是前者的平滑版。</p><p><span class="marginnote">奖励塑形就是「在只看对错的打分表上加一条附加评分项」：原来答对 1 分答错 0 分，现在答对之后还按长短加减零点几分。把「同样对，短的加分」写进打分规则，模型才学得会省话。</span></p><p>解码侧：budget forcing、收束提示、到达 \\(B\\) 强制 boxed。只在推理做、训练没见过，准确率会掉。应把若干 \\(B\\) 写入 RL 采样。</p><h3 id="控制的是思维长度还是答案长度" tabindex="-1">控制的是思维长度还是答案长度 <a class="header-anchor" href="#控制的是思维长度还是答案长度" aria-label="Permalink to &quot;控制的是思维长度还是答案长度&quot;">​</a></h3><p>用户可见答案应短；隐藏思维可长。分别塑形：思维段用 \\(B\\)，答案段用短惩罚。混成一个 \\(|y|\\) 会把证明写进用户答案或把思维压死。</p><p><span class="marginnote">GSPO / 样本级损失改的是梯度测度，不是长度目标。不要用换算法代替 \\(p(|y|)\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练：\\(R = R_{\\mathrm{acc}} + \\lambda p(|y_{\\mathrm{think}}|)\\)，\\(\\lambda\\) 按分桶金标扫。多档：每个 prompt 随机 \\(B\\in\\{2\\mathrm{K},8\\mathrm{K},16\\mathrm{K}\\}\\)，超 \\(B\\) 走截断协议（过长过滤课）。评测：各 \\(B\\) 的准确率表。解码：与训练 \\(B\\) 对齐的收束模板。</p><p><span class="marginnote">数字实例：\\(B\\in\\{2\\mathrm{K},8\\mathrm{K},16\\mathrm{K}\\}\\) 就是同一道题训练时随机限定「思维最多 2048 / 8192 / 16384 个 token」。三个档都练过，线上才敢说「这题只给 2K 预算」而准确率不塌；只练过 16K 的模型，突然限 2K 会慌。</span></p>',13)),(e(),o(A,null,{default:E(()=>[i(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACC%5B%22%E5%AF%B9%E9%94%99%20R_acc%22%5D%20--%3E%20MIX%5B%22%E5%90%8C%E6%A0%B7%E5%AF%B9%E5%88%99%E7%9F%AD%22%5D%0A%20%20LEN%5B%22p(%7Cy_think%7C)%22%5D%20--%3E%20MIX%0A%20%20MIX%20--%3E%20RL%5B%22GRPO%20%2F%20PPO%22%5D%0A%20%20B%5B%22%E9%9A%8F%E6%9C%BA%E9%A2%84%E7%AE%97%E6%A1%A3%22%5D%20--%3E%20RL%0A%20%20RL%20--%3E%20DEC%5B%22%E6%8E%A8%E7%90%86%E6%94%B6%E6%9D%9F%E4%B8%8E%E8%AE%AD%E7%BB%83%E5%90%8C%E6%A8%A1%E6%9D%BF%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"与混合模式：短模式 \\(\\lambda\\) 极大或 \\(B\\) 极小；思维模式 \\(\\lambda\\) 小。两个头比一个全局 \\(\\lambda\\) 干净。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[l("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"\\(\\lambda\\) 过大，模型牺牲难题搜索换短；过小，过度思考还在。分桶扫 \\(\\lambda\\)。首次正确位置损失（对有校验器的可中途判）能直接惩罚尾部废话，但训练要能多次调用校验器，贵。",-1)),(e(),o(A,null,{default:E(()=>[i(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAMB%7B%22%CE%BB%20%E5%8F%96%E5%A4%9A%E5%A4%A7%EF%BC%9F%22%7D%20--%3E%20BIG%5B%22%CE%BB%20%E8%BF%87%E5%A4%A7%EF%BC%9A%E4%B8%BA%E7%9F%AD%E7%89%BA%E7%89%B2%E9%9A%BE%E9%A2%98%E6%90%9C%E7%B4%A2%22%5D%0A%20%20LAMB%20--%3E%20SMALL%5B%22%CE%BB%20%E8%BF%87%E5%B0%8F%EF%BC%9A%E8%BF%87%E5%BA%A6%E6%80%9D%E8%80%83%E8%BF%98%E5%9C%A8%EF%BC%8C%E8%B4%A6%E5%8D%95%E7%85%A7%E6%97%A7%22%5D%0A%20%20BIG%20--%3E%20FIX%5B%22%E5%88%86%E6%A1%B6%E4%BD%93%E6%A3%80%EF%BC%9A%E9%9A%BE%E9%A2%98%E6%A1%B6%E4%B8%8E%E6%98%93%E9%A2%98%E6%A1%B6%E5%88%86%E5%BC%80%E7%9C%8B%22%5D%0A%20%20SMALL%20--%3E%20FIX%0A%20%20FIX%20--%3E%20OK%7B%22%E5%90%84%E6%A1%B6%E8%A1%A8%E7%8E%B0%E9%83%BD%E8%BE%BE%E6%A0%87%EF%BC%9F%22%7D%0A%20%20OK%20--%3E%7C%E5%90%A6%7C%20LAMB%0A%20%20OK%20--%3E%7C%E6%98%AF%7C%20LOCK%5B%22%E9%94%81%E5%AE%9A%20%CE%BB%EF%BC%8C%E8%BF%9B%E5%85%A5%E5%A4%9A%E6%A1%A3%20B%20%E8%AE%AD%E7%BB%83%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">这张图回答「长度惩罚系数 λ 怎么定」。它是个跷跷板：一头是难题被草草作答，一头是简单题上喋喋不休。所以不能只看平均分——难题桶掉分说明 λ 大了，平均长度压不下去说明 λ 小了。</span></p><p><span class="marginnote">长度控制会改变语言混杂与「wait」频率，因为那些 token 都占预算。后课 aha 可能被压掉，要看难题桶。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>开放生成没有 \\(R_{\\mathrm{acc}}\\)，长度控制退回 RM 惩罚，过优化风险回到 Gao。本课主场可验证推理。「对则偏短」是多目标，不要把长度除以 \\(|y|\\)；思维段与用户答案段分开塑形；\\(\\lambda\\) 与过长过滤的 \\(L_{\\max}\\) 不要两处各罚一次，叠罚等于把预算偷偷砍半。下一课自我验证与回溯：被长度控制删掉的可能是有用的「wait」。</p><p><span class="marginnote">常见误区：以为解码时截断（到预算就硬停）就等于长度控制。模型没在训练里见过「被截断后怎么收尾」，截出来的常是半句废话加一个硬凑答案。控制必须先进训练目标，截断只是最后的保险丝。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>长度控制是「对则偏短」的多目标，不是除以 \\(|y|\\)。</li><li>训练见过多档 \\(B\\) 与 \\(p(|y|)\\)；推理截断只是最后闸。</li><li>思维长度与用户答案长度分开塑形。</li><li>\\(\\lambda\\) 按难度分桶扫，防止打压长证明。</li><li>出处：Yu 等 DAPO shaping；Muennighoff 等 s1；R1 长度问题作动机。</li></ul>',7))])}const f=B(p,[["render",d]]);export{u as __pageData,f as default};
